// RUN: %clang -O2 %s --target=aie2ps -nostdlibinc -S -emit-llvm -o - | FileCheck %s

// Minimal reproducer for clang crash with unary minus on _Float16
// original case: L1/regression/misc/GeluLUT/GeluTemplated_wts_lut_aie2_fp16

// CHECK-LABEL: define dso_local noundef half @_Z16test_minus_constv(
// CHECK-SAME: ) local_unnamed_addr #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    ret half 0xH4500
//
float16 test_minus_const() {
    // Create a constexpr float16 value
    static constexpr float16 value = static_cast<float16>(-5.0f);

    // Unary minus on float16 constexpr causes the crash
    return -value;
}

// CHECK-LABEL: define dso_local noundef half @_Z19test_minus_variableDF16_(
// CHECK-SAME: half noundef [[A:%.*]]) local_unnamed_addr #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[FNEG:%.*]] = fneg half [[A]]
// CHECK-NEXT:    ret half [[FNEG]]
//
float16 test_minus_variable(float16 a) {
    return -a;
}
